/* Generated from desktop.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='desktop'],
[data-ui-theme='desktop'] {
  color-scheme: light;
  --ui-background: #f2efe9;
  --ui-foreground: #14120f;
  --ui-card: #ffffff;
  --ui-card-foreground: #14120f;
  --ui-popover: #ffffff;
  --ui-popover-foreground: #14120f;
  --ui-primary: #2659c2;
  --ui-primary-foreground: #ffffff;
  --ui-secondary: #e6e3dd;
  --ui-secondary-foreground: #14120f;
  --ui-muted: #f1eee9;
  --ui-muted-foreground: #5f5b53;
  --ui-accent: #e7eefb;
  --ui-accent-foreground: #1f4ea8;
  --ui-destructive: #ab3426;
  --ui-destructive-foreground: #ffffff;
  --ui-success: oklch(0.48 0.13 155);
  --ui-success-foreground: oklch(0.985 0 0);
  --ui-info: oklch(0.48 0.15 251);
  --ui-info-foreground: oklch(0.985 0 0);
  --ui-warning: oklch(0.49 0.15 70);
  --ui-warning-foreground: oklch(0.985 0 0);
  --ui-border: #e4ded2;
  --ui-input: #d6cfc0;
  --ui-ring: #2f6bdd;
  --ui-chart-1: #2f6bdd;
  --ui-chart-2: #2f9a72;
  --ui-chart-3: #d08a2a;
  --ui-chart-4: #d8503f;
  --ui-chart-5: #8a62d6;
  --ui-sidebar: #f2efe9;
  --ui-sidebar-foreground: #14120f;
  --ui-sidebar-primary: #2659c2;
  --ui-sidebar-primary-foreground: #ffffff;
  --ui-sidebar-accent: #e6e3dd;
  --ui-sidebar-accent-foreground: #14120f;
  --ui-sidebar-border: #e4ded2;
  --ui-sidebar-ring: #2f6bdd;
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.875rem;
  --ui-radius-action: initial;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-control-padding: 0.625rem;
  --ui-panel-spacing: 1rem;
  --ui-font-body: 'Geist', 'Geist Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --ui-font-heading: 'Geist', 'Geist Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --ui-font-mono: 'Geist Mono', 'Geist Mono Variable', ui-monospace, 'SFMono-Regular', Menlo, monospace;
  --ui-tracking-body: -0.005em;
  --ui-tracking-heading: -0.01em;
  --ui-leading-body: 1.5;
  --ui-leading-heading: 1.25;
  --ui-weight-body: 400;
  --ui-weight-heading: 600;
  --ui-weight-label: 500;
  --ui-shadow-control: 0 1px 2px oklch(0 0 0 / 0.04);
  --ui-shadow-panel:
    0 1px 2px oklch(0 0 0 / 0.04), 0 6px 18px -6px oklch(0 0 0 / 0.12);
  --ui-shadow-overlay:
    0 1px 2px oklch(0 0 0 / 0.05), 0 12px 32px -8px oklch(0 0 0 / 0.18);
  --ui-backdrop: oklch(0.21 0.01 70 / 0.28);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='desktop'].dark,
[data-ui-theme='desktop'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.165 0.014 260);
  --ui-foreground: oklch(0.95 0.005 255);
  --ui-card: oklch(0.195 0.016 260);
  --ui-card-foreground: oklch(0.95 0.005 255);
  --ui-popover: oklch(0.235 0.02 260);
  --ui-popover-foreground: oklch(0.95 0.005 255);
  --ui-primary: oklch(0.7 0.14 258);
  --ui-primary-foreground: oklch(0.165 0.014 260);
  --ui-secondary: oklch(0.21 0.014 260);
  --ui-secondary-foreground: oklch(0.95 0.005 255);
  --ui-muted: oklch(0.235 0.02 260);
  --ui-muted-foreground: oklch(0.71 0.018 257);
  --ui-accent: oklch(0.3 0.07 255);
  --ui-accent-foreground: oklch(0.95 0.005 255);
  --ui-destructive: oklch(0.75 0.16 25);
  --ui-destructive-foreground: oklch(0.165 0.014 260);
  --ui-success: oklch(0.76 0.12 155);
  --ui-success-foreground: oklch(0.15 0.02 255);
  --ui-info: oklch(0.76 0.12 251);
  --ui-info-foreground: oklch(0.15 0.02 255);
  --ui-warning: oklch(0.82 0.13 75);
  --ui-warning-foreground: oklch(0.15 0.02 255);
  --ui-border: oklch(0.285 0.017 260);
  --ui-input: oklch(0.35 0.02 260);
  --ui-ring: oklch(0.7 0.14 258);
  --ui-chart-1: oklch(0.7 0.14 258);
  --ui-chart-2: oklch(0.72 0.11 165);
  --ui-chart-3: oklch(0.8 0.13 75);
  --ui-chart-4: oklch(0.72 0.17 25);
  --ui-chart-5: oklch(0.7 0.13 300);
  --ui-sidebar: oklch(0.165 0.014 260);
  --ui-sidebar-foreground: oklch(0.95 0.005 255);
  --ui-sidebar-primary: oklch(0.7 0.14 258);
  --ui-sidebar-primary-foreground: oklch(0.165 0.014 260);
  --ui-sidebar-accent: oklch(0.21 0.014 260);
  --ui-sidebar-accent-foreground: oklch(0.95 0.005 255);
  --ui-sidebar-border: oklch(0.285 0.017 260);
  --ui-sidebar-ring: oklch(0.7 0.14 258);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.875rem;
  --ui-radius-action: initial;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-control-padding: 0.625rem;
  --ui-panel-spacing: 1rem;
  --ui-font-body: 'Geist', 'Geist Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --ui-font-heading: 'Geist', 'Geist Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --ui-font-mono: 'Geist Mono', 'Geist Mono Variable', ui-monospace, 'SFMono-Regular', Menlo, monospace;
  --ui-tracking-body: -0.005em;
  --ui-tracking-heading: -0.01em;
  --ui-leading-body: 1.5;
  --ui-leading-heading: 1.25;
  --ui-weight-body: 400;
  --ui-weight-heading: 600;
  --ui-weight-label: 500;
  --ui-shadow-control: 0 1px 2px oklch(0 0 0 / 0.3);
  --ui-shadow-panel:
    0 1px 2px oklch(0 0 0 / 0.3), 0 8px 24px -8px oklch(0 0 0 / 0.5);
  --ui-shadow-overlay:
    0 1px 2px oklch(0 0 0 / 0.3), 0 16px 40px -12px oklch(0 0 0 / 0.6);
  --ui-backdrop: oklch(0 0 0 / 0.5);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
